// INVENTORY_BULK_APPLY guard: request, session tenant, run nonce, and every list the SQL nodes bind (digits only)
const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
const DIG = /^[0-9]{1,20}$/;
const KEY = /^[A-Za-z0-9._-]{1,40}$/;
const MAX_MOVEMENTS = 5000;

const bulkGuard = function bulkGuard(inp) {
  const reject = (code, message) => ({ route: "REJECT", result_code: code, result_message: message });
  const mode = s(inp.mode).toUpperCase();
  const op = s(inp.operationKey);
  const org = s(inp.organizationId);
  const tenant = s(inp.tenantId);
  if (mode !== "PLAN" && mode !== "APPLY") return reject("REQUEST_INVALID", "mode must be PLAN or APPLY");
  if (!/^[A-Za-z0-9|:._-]{1,32}$/.test(op)) return reject("REQUEST_INVALID", "operation_key must be 1-32 of A-Z a-z 0-9 | : . _ -");
  if (!DIG.test(org)) return reject("REQUEST_INVALID", "organization_id must be digits");
  if (!DIG.test(tenant)) return reject("REQUEST_INVALID", "no session tenant");
  let list = inp.movements;
  if (typeof list === "string") {
    try {
      list = JSON.parse(list);
    } catch (e) {
      return reject("REQUEST_INVALID", "movements is not JSON");
    }
  }
  if (!Array.isArray(list) || !list.length) return reject("REQUEST_INVALID", "movements must be a non-empty array");
  if (list.length > MAX_MOVEMENTS) return reject("REQUEST_INVALID", "at most " + MAX_MOVEMENTS + " movements per operation");

  const seen = {};
  const mats = {};
  const balTuples = {};
  const batchTuples = {};
  const costPairs = {};
  const lockKeys = {};
  const effectKeys = [];
  for (let i = 0; i < list.length; i++) {
    const m = list[i] || {};
    const at = "movements[" + i + "] ";
    const key = s(m.movement_key);
    if (!KEY.test(key)) return reject("REQUEST_INVALID", at + "movement_key must be 1-40 of A-Z a-z 0-9 . _ -");
    if (seen[key]) return reject("REQUEST_INVALID", at + "movement_key " + key + " repeats");
    seen[key] = true;
    const dir = s(m.direction);
    if (dir !== "SUBTRACT" && dir !== "ADD") return reject("REQUEST_INVALID", at + "direction must be SUBTRACT or ADD");
    for (const f of ["material_id", "plant_id", "location_id"]) if (!DIG.test(s(m[f]))) return reject("REQUEST_INVALID", at + f + " must be digits");
    const batch = s(m.batch_id);
    if (batch && !DIG.test(batch)) return reject("REQUEST_INVALID", at + "batch_id must be digits or empty");
    if (s(m.organization_id) !== org) return reject("REQUEST_INVALID", at + "organization_id differs from the operation's");
    if (dir === "ADD" && s(m.batch_number) && s(m.batch_number) !== "-" && !batch) return reject("UNSUPPORTED_NEW_BATCH", at + "creating a new batch is not supported yet");
    if (m.unit_price_from !== undefined && m.unit_price_from !== null && s(m.unit_price_from) !== "" && !seen[s(m.unit_price_from)]) {
      return reject("REQUEST_INVALID", at + "unit_price_from must name an earlier movement");
    }
    const mat = s(m.material_id);
    const loc = s(m.location_id);
    const plant = s(m.plant_id);
    mats[mat] = true;
    balTuples["[" + mat + "," + loc + "," + plant + "]"] = true;
    costPairs["[" + mat + "," + plant + "]"] = true;
    lockKeys["ITEM|" + mat + "|" + loc] = true;
    // plant-level FIFO / WA rows: written by every movement that is not a category move (core.js isMovingInv 0)
    const moving = m.isMovingInv === undefined || m.isMovingInv === null ? 0 : Number(m.isMovingInv);
    if (moving !== 1) lockKeys["COST|" + mat + "|" + plant] = true;
    if (batch) {
      batchTuples["[" + mat + "," + loc + "," + batch + "," + plant + "]"] = true;
      lockKeys["BATCH|" + mat + "|" + loc + "|" + batch] = true;
    }
    effectKeys.push(op + "|" + key);
  }
  const keys = Object.keys(lockKeys).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  // lists reach the SQL as ONE bound JSON string, unpacked by JSON_TABLE (ids stay exact: digits become JSON integers)
  const jsonList = (o) => "[" + Object.keys(o).join(",") + "]";
  return {
    route: "GO",
    result_code: "",
    result_message: "",
    mode: mode,
    operationKey: op,
    organizationId: org,
    tenantId: tenant,
    nonce: (s(inp.uuid).replace(/[^0-9a-fA-F]/g, "") + "000000000000").slice(0, 12),
    count: list.length,
    materialIdsCsv: Object.keys(mats).join(",") || "0",
    balTuplesJson: jsonList(balTuples),
    batchTuplesJson: jsonList(batchTuples),
    costPairsJson: jsonList(costPairs),
    effectKeysJson: JSON.stringify(effectKeys),
    lockKeys: keys,
    lockKeysJson: JSON.stringify(keys),
  };
};

return bulkGuard({
  mode: [{{workflowparams:mode}}][0],
  operationKey: [{{workflowparams:operation_key}}][0],
  organizationId: [{{workflowparams:organization_id}}][0],
  movements: [{{workflowparams:movements}}][0],
  tenantId: [{{system:tenantId}}][0],
  uuid: [{{system:uuid}}][0],
});

// INVENTORY_BULK_APPLY state: DONE -> replay its stored answer; REVIEW -> stop; intent rows -> resume; else fresh. Run marker
// IBA|RUN|nnn (heartbeat in finished_at): the latest generation RUNNING with a heartbeat under 20 min = another call of this operation
// is alive -> BUSY; else this APPLY call takes the next generation (CLAIM); PLAN and REVIEW write nothing (SKIP)
const s = (v) => (v === undefined || v === null ? "" : String(v));
const RUN_STALE_S = 1200;
const rows = [{{node:sql_node_IBops.data}}][0];
const list = Array.isArray(rows) ? rows : rows ? [rows] : [];
const mode = s([{{node:code_node_IBguard.data.mode}}][0]);
let done = null;
let review = null;
let mark = null;
const intent = [];
let dbNow = "";
for (const r of list) {
  if (!r) continue;
  if (!dbNow && r.db_now) dbNow = s(r.db_now);
  const name = s(r.step_name);
  if (name === "IBA|DONE") done = r;
  else if (name === "IBA|REVIEW") review = r;
  else if (name.indexOf("IBA|I|") === 0) intent.push(r);
  else if (name.indexOf("IBA|RUN|") === 0) {
    const g = parseInt(name.slice(8), 10) || 0;
    if (!mark || g > mark.gen) mark = { gen: g, status: s(r.step_status), hb: s(r.heartbeat) };
  }
}
intent.sort((a, b) => (s(a.step_name) < s(b.step_name) ? -1 : 1));
let route = "FRESH";
if (mode === "PLAN") route = "PLAN";
else if (done) route = "REPLAY";
else if (review) route = "REVIEW";
else if (intent.length) route = "RESUME";
let stored = {};
if (done) {
  try {
    stored = JSON.parse(s(done.result_ref) || "{}");
  } catch (e) {
    stored = {};
  }
}
const at = (v) => Date.parse(s(v).replace(" ", "T"));
const age = mark && mark.hb && dbNow ? (at(dbNow) - at(mark.hb)) / 1000 : Infinity;
const live = !!mark && mark.status === "RUNNING" && age < RUN_STALE_S;
const runGate = mode !== "APPLY" || route === "REVIEW" ? "SKIP" : live ? "BUSY" : "CLAIM";
const gen = (mark ? mark.gen : 0) + 1;
return {
  route: route,
  dbNow: dbNow,
  intentText: intent.map((r) => s(r.result_ref)).join(""),
  intentParts: String(intent.length),
  storedResults: stored.results || [],
  storedSummary: stored.summary || {},
  reviewReason: review ? s(review.error_message) : "",
  runGate: runGate,
  runGen: String(gen),
  runStep: "IBA|RUN|" + String(gen).padStart(3, "0"),
  runMessage: live ? "the same operation is still running (run " + mark.gen + ", last heartbeat " + mark.hb + "); try again later" : "",
};

// INVENTORY_BULK_APPLY run marker: this call's generation (unique job / step: a twin call inserting the same generation fails its run)
const s = (v) => (v === undefined || v === null ? "" : String(v));
const st = [{{node:code_node_IBstate.data}}][0] || {};
return { rows: [{ job_id: s([{{node:code_node_IBguard.data.operationKey}}][0]), organization_id: s([{{node:code_node_IBguard.data.organizationId}}][0]),
  step_name: s(st.runStep), step_status: "RUNNING", attempt_count: 0, result_ref: s([{{node:code_node_IBguard.data.nonce}}][0]), started_at: s(st.dbNow),
  finished_at: s(st.dbNow), error_code: "", error_message: "" }] };

// INVENTORY_BULK_APPLY run marker read back: the row id the heartbeats and the end update, and that it carries this run's nonce
const s = (v) => (v === undefined || v === null ? "" : String(v));
const rows = [{{node:sql_node_IBrunMe.data}}][0];
const r = (Array.isArray(rows) ? rows : rows ? [rows] : [])[0] || {};
const own = s(r.result_ref) !== "" && s(r.result_ref) === s([{{node:code_node_IBguard.data.nonce}}][0]) && /^[0-9]{1,20}$/.test(s(r.id));
return { own: own ? "YES" : "NO", runId: own ? s(r.id) : "", dbNow: s(r.db_now) };

// INVENTORY_BULK_APPLY lock release plan: this operation's rows only (owner cleared first, then GIVE adds the token back); a row its
// own earlier release left between the two (owner empty, last owner = this operation) goes straight to GIVE
const s = (v) => (v === undefined || v === null ? "" : String(v));
const op = s([{{node:code_node_IBguard.data.operationKey}}][0]);
const rows = [{{node:sql_node_IBrpRel.data}}][0];
const list = Array.isArray(rows) ? rows : rows ? [rows] : [];
let dbNow = "";
for (const r of list) if (r && !dbNow && r.db_now) dbNow = s(r.db_now);
const clearRows = [];
const plusIds = [];
for (const r of list) {
  if (!r || !/^[0-9]{1,20}$/.test(s(r.id)) || Number(r.free_token) !== 0) continue;
  if (s(r.owner_operation_id) === op) {
    clearRows.push({ id: s(r.id), owner_operation_id: "", last_owner_operation_id: op, last_released_at: dbNow, lock_version: (Number(r.lock_version) || 0) + 1 });
    plusIds.push(s(r.id));
  } else if (s(r.owner_operation_id) === "" && s(r.last_owner_operation_id) === op) plusIds.push(s(r.id));
}
const batches = [];
for (let i = 0; i < clearRows.length; i += 250) batches.push({ from: i });
return { clearRows: clearRows, batches: batches, plusIds: plusIds, needRelease: plusIds.length ? "YES" : "NO" };

// INVENTORY_BULK_APPLY slice of clearRows: rows [index * 250, + 250)
const all = [{{node:code_node_IBrpRelease.data.clearRows}}][0];
const list = Array.isArray(all) ? all : all ? [all] : [];
const raw = [{{node:get_cache_IBrpIdx.data}}][0];
const index = raw === undefined || raw === null || String(raw).trim() === "" ? 0 : parseInt(String(raw).replace(/"/g, ""), 10) || 0;
const rows = list.slice(index * 250, index * 250 + 250);
return { rows: rows, count: String(rows.length), nextIndex: String(index + 1) };

// INVENTORY_BULK_APPLY lock seed: a lock row per key, inserted once (free_token 1), as INVENTORY_APPLY_OPERATION seeds them
const s = (v) => (v === undefined || v === null ? "" : String(v));
const keys = [{{node:code_node_IBguard.data.lockKeys}}][0] || [];
const org = s([{{node:code_node_IBguard.data.organizationId}}][0]);
const rows = [{{node:sql_node_IBlk1.data}}][0];
const list = Array.isArray(rows) ? rows : rows ? [rows] : [];
const have = {};
const deleted = [];
for (const r of list) {
  if (!r || r.lock_key === undefined || r.lock_key === null || r.lock_key === "") continue;
  have[s(r.lock_key).toUpperCase()] = true;
  if (Number(r.is_deleted || 0) !== 0) deleted.push(s(r.lock_key));
}
if (deleted.length) throw new Error("IBA_LOCK_SEED: soft-deleted lock rows occupy " + deleted.join(","));
const rowsToAdd = [];
for (const k of keys) {
  if (have[k.toUpperCase()]) continue;
  rowsToAdd.push({ organization_id: org, lock_key: k, balance_type: k.split("|")[0], free_token: 1, lock_version: 0, owner_operation_id: "", last_owner_operation_id: "" });
}
const batches = [];
for (let i = 0; i < rowsToAdd.length; i += 250) batches.push({ from: i });
return { rowsToAdd: rowsToAdd, batches: batches, needSeed: rowsToAdd.length ? "YES" : "NO" };

// INVENTORY_BULK_APPLY lock claim: keys in lock order; a key another operation holds, or whose lock row the seed could not
// create (another operation inserted it first) -> BUSY before any take; a key this operation already holds (a run that died) is kept
const s = (v) => (v === undefined || v === null ? "" : String(v));
const keys = [{{node:code_node_IBguard.data.lockKeys}}][0] || [];
const op = s([{{node:code_node_IBguard.data.operationKey}}][0]);
// held by it, or left by its own release between clearing the owner and GIVE (a run that died there)
const mine = (r) => s(r.owner_operation_id) === op || (s(r.owner_operation_id) === "" && s(r.last_owner_operation_id) === op);
const rows = [{{node:sql_node_IBlk2.data}}][0];
const list = Array.isArray(rows) ? rows : rows ? [rows] : [];
const byKey = {};
let dbNow = "";
for (const r of list) {
  if (!r || !r.lock_key) continue;
  byKey[s(r.lock_key).toUpperCase()] = r;
  if (!dbNow && r.db_now) dbNow = s(r.db_now);
}
const take = [];
const busy = [];
for (const k of keys) {
  const r = byKey[k.toUpperCase()];
  if (!r || !/^[0-9]{1,20}$/.test(s(r.id))) {
    busy.push(k + " (lock row not created yet)");
    continue;
  }
  const t = Number(r.free_token);
  if (t === 1) take.push(s(r.id));
  else if (t === 0 && mine(r)) continue;
  else busy.push(k + (s(r.owner_operation_id) ? " (" + s(r.owner_operation_id) + ")" : ""));
}
const route = busy.length ? "BUSY" : take.length ? "TAKE" : "HELD";
if (route === "TAKE" && !dbNow) throw new Error("IBA_LOCK_INPUT: the lock read returned no db_now");
return { route: route, ids: take, claimedAt: dbNow, busy: busy.slice(0, 20).join(", "), busyCount: String(busy.length) };

// INVENTORY_BULK_APPLY lock verify: every key reads token 0 held by this operation (as claimed), else LOST
const s = (v) => (v === undefined || v === null ? "" : String(v));
const keys = [{{node:code_node_IBguard.data.lockKeys}}][0] || [];
const op = s([{{node:code_node_IBguard.data.operationKey}}][0]);
const mine = (r) => s(r.owner_operation_id) === op || (s(r.owner_operation_id) === "" && s(r.last_owner_operation_id) === op);
const rows = [{{node:sql_node_IBlk3.data}}][0];
const list = Array.isArray(rows) ? rows : rows ? [rows] : [];
const byKey = {};
for (const r of list) if (r && r.lock_key) byKey[s(r.lock_key).toUpperCase()] = r;
const lost = [];
for (const k of keys) {
  const r = byKey[k.toUpperCase()];
  if (!r || Number(r.free_token) !== 0 || !mine(r)) lost.push(k);
}
const first = list.find((r) => r && r.db_now) || {};
return { route: lost.length ? "LOST" : "HELD", lost: lost.slice(0, 20).join(","), lostCount: String(lost.length), dbNow: s(first.db_now) };

// INVENTORY_BULK_APPLY plan: replay the movements over the rows read (fresh), or compare a stored intent with them (resume)
// INVENTORY_BULK_APPLY planner. Replays SUBTRACT_INVENTORY_NEW / ADD_INVENTORY_NEW in list order over in-memory
// copies of the rows those workflows read, so every movement sees the writes of the ones before it, then returns
// each touched row once (before/after) plus the inventory_movement rows. All-or-nothing: the first movement the old
// workflows would fail fails the whole plan and nothing is written.
const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
const s = (v) => (v === undefined || v === null ? "" : String(v));
const CATEGORY_FIELD = {
  Unrestricted: "unrestricted_qty",
  Reserved: "reserved_qty",
  Blocked: "block_qty",
  "Quality Inspection": "qualityinsp_qty",
  "In Transit": "intransit_qty",
};
const QTY_COLS = ["unrestricted_qty", "reserved_qty", "block_qty", "qualityinsp_qty", "intransit_qty", "balance_quantity"];
const FIFO = "First In First Out";
const WA = "Weighted Average";
const FIXED = "Fixed Cost";

// a stored decimal as the platform keeps it: dp decimals of the exact 8-dp value, mode = the number rule's precision_rule
// (1 round half-up, 2 truncate toward zero, 3 away from zero)
function roundDec(v, dp, mode) {
  const x = q8(v);
  if (!(dp >= 0 && dp < 8)) return x;
  const t = Math.abs(x).toFixed(8);
  const cut = t.indexOf(".") + 1 + dp;
  let head = t.slice(0, cut);
  const rest = t.slice(cut);
  const up = Number(mode) === 2 ? false : Number(mode) === 3 ? /[1-9]/.test(rest) : rest.charCodeAt(0) >= 53;
  if (up) {
    const digits = head.replace(".", "").split("");
    let i = digits.length - 1;
    while (i >= 0 && digits[i] === "9") digits[i--] = "0";
    if (i < 0) digits.unshift("1");
    else digits[i] = String(Number(digits[i]) + 1);
    const intLen = digits.length - dp;
    head = digits.slice(0, intLen).join("") + (dp ? "." + digits.slice(intLen).join("") : "");
  }
  const r = Number(head.replace(/\.$/, ""));
  return x < 0 && r !== 0 ? -r : r;
}
const roundHalfUp = (v, dp) => roundDec(v, dp, 1);
// the written numbers bound to "Inventory Price" (schema numberRule); every other one is "Inventory Qty"
const PRICE_COLUMNS = { unit_price: 1, total_price: 1, fifo_cost_price: 1, wa_cost_price: 1 };

function planBulk(input) {
  const movements = Array.isArray(input.movements) ? input.movements : [];
  const items = input.items || {};
  const nowText = input.nowText || "";
  // the tenant's number rules: a stored column holds what the platform rounded it to, and a later movement reads that back
  // (as the old path's next call did). input.precision = { price, qty, columns: { "<table>.<column>": rule } }, a rule
  // being { dp, mode } (a bare number = dp, half-up); none = 8 dp
  const P = input.precision || {};
  const ruleOf = (r) => (r === undefined || r === null ? null : typeof r === "number" ? { dp: r, mode: 1 } : r);
  const rc = (table, col, v) => {
    const cols = P.columns || {};
    const r = ruleOf(Object.prototype.hasOwnProperty.call(cols, table + "." + col) ? cols[table + "." + col] : PRICE_COLUMNS[col] ? P.price : P.qty);
    return r && r.dp !== null && r.dp !== undefined ? roundDec(v, r.dp, r.mode) : q8(v);
  };
  let seq = 0;
  const newId = (kind) => "new:" + kind + ":" + ++seq;

  // ---------------------------------------------------------------- indexed state (copies; originals kept for before)
  const index = (rows, keyOf) => {
    const map = {};
    const dup = {};
    for (const r of rows || []) {
      const k = keyOf(r);
      if (map[k]) dup[k] = true;
      else map[k] = r;
    }
    return { map, dup };
  };
  const cloneRows = (rows) => (rows || []).map((r) => Object.assign({}, r, { id: s(r.id) }));
  const balKey = (m, loc, plant, org) => [s(m), s(loc), s(plant), s(org)].join("|");
  const batchKey = (m, loc, batch, plant, org) => [s(m), s(loc), s(batch), s(plant), s(org)].join("|");
  const costKey = (m, plant, org, batch) => [s(m), s(plant), s(org), s(batch)].join("|");

  const itemBalIdx = index(cloneRows(input.itemBalances), (r) => balKey(r.material_id, r.location_id, r.plant_id, r.organization_id));
  const batchBalIdx = index(cloneRows(input.batchBalances), (r) => batchKey(r.material_id, r.location_id, r.batch_id, r.plant_id, r.organization_id));
  const fifoRows = cloneRows(input.fifoLayers);
  const waRows = cloneRows(input.waRows);

  const before = { item_balance: {}, item_batch_balance: {}, fifo: {}, wa: {} };
  const touched = { item_balance: {}, item_batch_balance: {}, fifo: {}, wa: {} };
  const created = { item_balance: [], item_batch_balance: [], fifo: [], wa: [], batch: [] };
  // a column first touched by a later movement joins the row's snapshot (its value is still the one read)
  const snap = (table, row, cols) => {
    if (row.id.indexOf("new:") === 0) return;
    const b = before[table][row.id] || (before[table][row.id] = {});
    for (const c of cols) if (!(c in b)) b[c] = row[c] === undefined ? null : row[c];
  };
  const touch = (table, row) => {
    if (row.id.indexOf("new:") !== 0) touched[table][row.id] = row;
  };

  const results = [];
  const movementRows = [];
  const byKey = {};
  const fail = (m, code, message) => ({ ok: false, failure: { code, movement_key: s(m && m.movement_key), message }, results });

  const uomOf = (item, m) => {
    const altQty = q8(parseFloat(m.quantity));
    let baseQty = altQty;
    const altUOM = m.material_uom || item.based_uom;
    const conv = Array.isArray(item.table_uom_conversion) ? item.table_uom_conversion.find((c) => c.alt_uom_id === altUOM) : null;
    if (conv) baseQty = q8(altQty * conv.base_qty);
    return { altQty, baseQty, altUOM, baseUOM: item.based_uom, method: item.material_costing_method };
  };
  const fifoFor = (m, plant, org, batch) => fifoRows.filter((r) => costKey(r.material_id, r.plant_id, r.organization_id, r.batch_id) === costKey(m, plant, org, batch));
  const waFor = (m, plant, org, batch) => waRows.filter((r) => costKey(r.material_id, r.plant_id, r.organization_id, r.batch_id) === costKey(m, plant, org, batch));
  const newestWa = (rows) =>
    rows.slice().sort((a, b) => (a.created_at && b.created_at ? new Date(b.created_at) - new Date(a.created_at) : 0))[0];

  for (const m of movements) {
    const key = s(m.movement_key);
    if (!key || byKey[key]) return fail(m, "REQUEST_INVALID", "movement_key missing or repeated: " + key);
    const dir = s(m.direction);
    if (dir !== "SUBTRACT" && dir !== "ADD") return fail(m, "REQUEST_INVALID", "direction must be SUBTRACT or ADD");

    // a release pair: the ADD takes the price and dates its SUBTRACT computed (GD_UNUSED_FN_NEW passes them on)
    if (m.unit_price_from) {
      const src = byKey[s(m.unit_price_from)];
      if (!src) return fail(m, "REQUEST_INVALID", "unit_price_from " + s(m.unit_price_from) + " is not an earlier movement");
      m.unit_price = src.unit_price;
      m.manufacturing_date = src.manufacturing_date;
      m.expired_date = src.expired_date;
    }

    const qtyNum = parseFloat(m.quantity);
    const missing = !s(m.material_id) || m.quantity === undefined || m.quantity === null || !(qtyNum > 0) || !s(m.plant_id) || !s(m.organization_id);
    if (missing || (dir === "SUBTRACT" && !s(m.inventory_category))) return fail(m, "VALIDATION_FAILED", "Validation Failed");
    if (s(m.unit_price) !== "" && q8(m.unit_price) < 0) return fail(m, "UNSUPPORTED_PRICE", "Negative unit price " + s(m.unit_price));

    const item = items[s(m.material_id)];
    if (!item) return fail(m, "ITEM_NOT_FOUND", "Item " + s(m.material_id) + " not found");
    if (Number(item.stock_control) === 0) {
      const r = { movement_key: key, direction: dir, code: "401", message: "Skipping inventory update for item (stock control = 0)" };
      results.push(r);
      byKey[key] = r;
      continue;
    }
    const u = uomOf(item, m);
    const isMovingInv = m.isMovingInv === undefined || m.isMovingInv === null ? 0 : Number(m.isMovingInv);
    const plant = s(m.plant_id);
    const org = s(m.organization_id);
    const mat = s(m.material_id);
    const loc = s(m.location_id);

    if (dir === "SUBTRACT") {
      const batch = s(m.batch_id);
      const categoryField = CATEGORY_FIELD[m.inventory_category];
      const bk = balKey(mat, loc, plant, org);
      if (itemBalIdx.dup[bk]) return fail(m, "DUPLICATE_BALANCE", "More than one item_balance row for " + bk);
      const itemRow = itemBalIdx.map[bk] || null;
      let batchRow = null;
      if (batch) {
        const tk = batchKey(mat, loc, batch, plant, org);
        if (batchBalIdx.dup[tk]) return fail(m, "DUPLICATE_BALANCE", "More than one item_batch_balance row for " + tk);
        batchRow = batchBalIdx.map[tk] || null;
        if (!batchRow && !itemRow) return fail(m, "BALANCE_NOT_FOUND", "Balance not found");
      }
      const existing = (batch ? batchRow : itemRow) || {};
      let mfg = m.manufacturing_date || null;
      let exp = m.expired_date || null;
      if (batch && (!mfg || !exp)) {
        mfg = existing.manufacturing_date === undefined ? null : existing.manufacturing_date;
        exp = existing.expired_date === undefined ? null : existing.expired_date;
      }
      if (q8(existing[categoryField] || 0) < u.baseQty) return fail(m, "INSUFFICIENT", "Insufficient quantity");

      const fifo = fifoFor(mat, plant, org, batch || null);
      const wa = waFor(mat, plant, org, batch || null);
      // SUBTRACT's "Migration Condition": the old branch rewrites costing rows from stale reads - refused here. A
      // category move with its price given reads and writes no costing row, so it goes through
      const priced = isMovingInv === 1 && q8(m.unit_price) > 0;
      if (!priced && ((wa.length > 0 && fifo.length > 0) || (u.method === FIFO && fifo.length === 0 && wa.length > 0) || (u.method === WA && wa.length === 0 && fifo.length > 0))) {
        return fail(m, "UNSUPPORTED_COSTING", "Item " + mat + " has costing rows that need migration (FIFO " + fifo.length + ", WA " + wa.length + ")");
      }

      let price = 0;
      if (isMovingInv === 1 && m.unit_price) price = q8(m.unit_price);
      else if (u.method === FIFO) price = fifoUnitPrice(fifo, u.baseQty);
      else if (u.method === WA) price = wa.length ? q8(newestWa(wa).wa_cost_price || 0) : 0;
      else if (u.method === FIXED) price = q8(parseFloat(item.purchase_unit_price || 0));
      if (price < 0) return fail(m, "UNSUPPORTED_PRICE", "Negative unit price " + price + " for material " + mat);
      const totalPrice = q8(price * u.baseQty);

      const deduct = (row) => {
        const tb = row === itemRow ? "item_balance" : "item_batch_balance";
        snap(tb, row, QTY_COLS);
        for (const c of QTY_COLS.slice(0, 5)) row[c] = rc(tb, c, q8(row[c] || 0) - (c === categoryField ? u.baseQty : 0));
        row.balance_quantity = rc(tb, "balance_quantity", q8(row.balance_quantity || 0) - u.baseQty);
      };
      if (itemRow) {
        deduct(itemRow);
        touch("item_balance", itemRow);
      }
      if (batch && batchRow) {
        snap("item_batch_balance", batchRow, QTY_COLS);
        for (const c of QTY_COLS.slice(0, 5)) batchRow[c] = rc("item_batch_balance", c, q8(batchRow[c] || 0) - (c === categoryField ? u.baseQty : 0));
        batchRow.balance_quantity = rc("item_batch_balance", "balance_quantity", q8(batchRow.balance_quantity || 0) - u.baseQty);
        touch("item_batch_balance", batchRow);
      }

      if (isMovingInv === 0) {
        if (u.method === FIFO) {
          let remaining = q8(u.baseQty);
          for (const layer of fifo.slice().sort((a, b) => (a.fifo_sequence || 0) - (b.fifo_sequence || 0))) {
            if (remaining <= 0) break;
            const avail = q8(layer.fifo_available_quantity || 0);
            if (avail <= 0) continue;
            const take = Math.min(remaining, avail);
            snap("fifo", layer, ["fifo_available_quantity"]);
            layer.fifo_available_quantity = rc("fifo_costing_history", "fifo_available_quantity", avail - take);
            touch("fifo", layer);
            remaining = q8(remaining - take);
          }
        } else if (u.method === WA) {
          const doc = newestWa(wa);
          if (!doc) {
            return fail(m, "NO_WA_RECORD", "No Weighted Average costing record for material " + mat + ", batch " + (batch || "(none)") + ", plant " + plant + " -- create the costing record for this plant before issuing this stock.");
          }
          snap("wa", doc, ["wa_quantity", "wa_cost_price"]);
          doc.wa_quantity = Math.max(0, rc("wa_costing_method", "wa_quantity", q8(doc.wa_quantity || 0) - q8(u.baseQty)));
          touch("wa", doc);
        }
      }

      movementRows.push({
        operation_effect_key: s(input.operationKey) + "|" + key,
        transaction_type: m.transaction_type,
        trx_no: m.trx_no,
        inventory_category: m.inventory_category,
        parent_trx_no: m.parent_trx_no === undefined ? null : m.parent_trx_no,
        movement: "OUT",
        plant_id: plant,
        organization_id: org,
        unit_price: rc("inventory_movement", "unit_price", price),
        total_price: rc("inventory_movement", "total_price", totalPrice),
        quantity: rc("inventory_movement", "quantity", u.altQty),
        base_qty: rc("inventory_movement", "base_qty", u.baseQty),
        uom_id: u.altUOM,
        base_uom_id: u.baseUOM,
        item_id: mat,
        bin_location_id: loc,
        batch_number_id: batch || null,
        costing_method_id: u.method,
        manufacturing_date: mfg,
        expired_date: exp,
        doc_date: m.doc_date,
        actual_qty: rc("inventory_movement", "actual_qty", -u.altQty),
        actual_base_qty: rc("inventory_movement", "actual_base_qty", -u.baseQty),
        handling_unit_id: m.handling_unit_id === undefined ? null : m.handling_unit_id,
      });
      const r = { movement_key: key, direction: dir, code: "200", unit_price: price, total_price: totalPrice, manufacturing_date: mfg, expired_date: exp };
      results.push(r);
      byKey[key] = r;
      continue;
    }

    // ------------------------------------------------------------------------------------------------ ADD
    const trx = m.transaction_type;
    let unitPrice = m.unit_price;
    let totalPrice = unitPrice * u.baseQty;
    let costPrice = null;
    let fixedPrice = null;
    if (trx !== undefined && trx !== null && trx !== "LOT") {
      if (u.method === FIFO || u.method === WA) {
        let up = q8(m.unit_price);
        let tp = q8(up * u.baseQty);
        if (trx === "GRN") {
          const poQ = q8(parseFloat(m.po_quantity) || 0);
          const amt = q8(parseFloat(m.po_amount) || 0);
          const conversion = q8(u.baseQty / parseFloat(m.quantity));
          const rate = m.exchange_rate || 1;
          const ppu = poQ > 0 ? q8(amt / poQ) : 0;
          up = q8((ppu / conversion) * rate);
          tp = q8(up * u.baseQty);
        }
        costPrice = { up, tp };
      } else {
        const up = q8(item.purchase_unit_price);
        fixedPrice = { up, tp: q8(up * u.baseQty) };
      }
    }
    if (trx !== "LOT") {
      if (u.method === FIFO || u.method === WA) {
        unitPrice = costPrice ? costPrice.up : undefined;
        totalPrice = costPrice ? costPrice.tp : undefined;
      } else if (u.method === FIXED) {
        unitPrice = fixedPrice ? fixedPrice.up : undefined;
        totalPrice = fixedPrice ? fixedPrice.tp : undefined;
      }
    }
    unitPrice = q8(unitPrice);
    totalPrice = q8(totalPrice);
    if (unitPrice < 0 || totalPrice < 0) return fail(m, "UNSUPPORTED_PRICE", "Negative unit price " + unitPrice + " for material " + mat);

    let batchId = m.batch_id || null;
    if (m.batch_number !== "-" && m.batch_number && !m.batch_id) {
      batchId = newId("batch");
      created.batch.push({
        id: batchId,
        batch_number: m.batch_number,
        material_id: mat,
        initial_quantity: rc("batch", "initial_quantity", u.baseQty),
        transaction_no: m.trx_no,
        plant_id: plant,
        organization_id: org,
        remark: m.remark === undefined ? null : m.remark,
        remark2: m.remark2 === undefined ? null : m.remark2,
        remark3: m.remark3 === undefined ? null : m.remark3,
        manufacturing_date: m.manufacturing_date === undefined ? null : m.manufacturing_date,
        expired_date: m.expired_date === undefined ? null : m.expired_date,
      });
    }

    const add = { unrestricted_qty: 0, reserved_qty: 0, block_qty: 0, qualityinsp_qty: 0, intransit_qty: 0 };
    const cat = m.inventory_category;
    const col = cat === "Blocked" ? "block_qty" : cat === "Reserved" ? "reserved_qty" : cat === "Quality Inspection" ? "qualityinsp_qty" : cat === "In Transit" ? "intransit_qty" : "unrestricted_qty";
    add[col] = q8(parseFloat(u.baseQty || 0));
    add.balance_quantity = q8(add.block_qty + add.reserved_qty + add.unrestricted_qty + add.qualityinsp_qty + add.intransit_qty);
    const stored = (table) => {
      const o = {};
      for (const c of QTY_COLS) o[c] = rc(table, c, add[c]);
      return o;
    };

    if (batchId) {
      const tk = batchKey(mat, loc, batchId, plant, org);
      if (batchBalIdx.dup[tk]) return fail(m, "DUPLICATE_BALANCE", "More than one item_batch_balance row for " + tk);
      const row = batchBalIdx.map[tk];
      if (row) {
        snap("item_batch_balance", row, QTY_COLS.concat(["remark", "remark2", "remark3"]));
        for (const c of QTY_COLS) row[c] = rc("item_batch_balance", c, q8(row[c] || 0) + q8(add[c] || 0));
        const remarkOf = (nv, ev) => (nv != null && nv !== ev ? nv : ev || "");
        row.remark = remarkOf(m.remark, row.remark);
        row.remark2 = remarkOf(m.remark2, row.remark2);
        row.remark3 = remarkOf(m.remark3, row.remark3);
        touch("item_batch_balance", row);
      } else {
        const nr = Object.assign({ id: newId("item_batch_balance"), material_id: mat, material_uom: u.baseUOM, location_id: loc }, stored("item_batch_balance"), {
          batch_id: batchId,
          plant_id: plant,
          organization_id: org,
          doc_date: m.doc_date === undefined ? null : m.doc_date,
          manufacturing_date: m.manufacturing_date === undefined ? null : m.manufacturing_date,
          expired_date: m.expired_date === undefined ? null : m.expired_date,
          remark: m.remark === undefined ? null : m.remark,
          remark2: m.remark2 === undefined ? null : m.remark2,
          remark3: m.remark3 === undefined ? null : m.remark3,
        });
        batchBalIdx.map[tk] = nr;
        created.item_batch_balance.push(nr);
      }
    }
    const bk = balKey(mat, loc, plant, org);
    if (itemBalIdx.dup[bk]) return fail(m, "DUPLICATE_BALANCE", "More than one item_balance row for " + bk);
    const itemRow = itemBalIdx.map[bk];
    if (itemRow) {
      snap("item_balance", itemRow, QTY_COLS);
      for (const c of QTY_COLS) itemRow[c] = rc("item_balance", c, q8(itemRow[c] || 0) + q8(add[c] || 0));
      touch("item_balance", itemRow);
    } else {
      const nr = Object.assign({ id: newId("item_balance"), material_id: mat, material_uom: u.baseUOM, location_id: loc }, stored("item_balance"), { plant_id: plant, organization_id: org });
      itemBalIdx.map[bk] = nr;
      created.item_balance.push(nr);
    }

    if (isMovingInv === 0) {
      if (u.method === FIFO) {
        const layers = fifoFor(mat, plant, org, batchId);
        const next = layers.length ? Math.max(...layers.map((l) => parseInt(l.fifo_sequence || 0, 10)), 0) + 1 : 1;
        const layer = {
          id: newId("fifo"),
          fifo_cost_price: rc("fifo_costing_history", "fifo_cost_price", unitPrice),
          fifo_initial_quantity: rc("fifo_costing_history", "fifo_initial_quantity", u.baseQty),
          fifo_available_quantity: rc("fifo_costing_history", "fifo_available_quantity", u.baseQty),
          material_id: mat,
          batch_id: batchId,
          fifo_sequence: String(next),
          plant_id: plant,
          organization_id: org,
        };
        fifoRows.push(layer);
        created.fifo.push(layer);
      } else if (u.method === WA) {
        if (batchId) {
          const row = { id: newId("wa"), wa_cost_price: rc("wa_costing_method", "wa_cost_price", unitPrice), wa_quantity: rc("wa_costing_method", "wa_quantity", u.baseQty), material_id: mat, batch_id: batchId, plant_id: plant, organization_id: org, created_at: nowText };
          waRows.push(row);
          created.wa.push(row);
        } else {
          const any = waRows.filter((r) => s(r.material_id) === mat && s(r.plant_id) === plant && s(r.organization_id) === org);
          if (any.length) {
            const latest = newestWa(any);
            const wc = q8(latest.wa_cost_price);
            const wq = q8(latest.wa_quantity);
            const nq = q8(wq + u.baseQty);
            snap("wa", latest, ["wa_quantity", "wa_cost_price"]);
            latest.wa_cost_price = rc("wa_costing_method", "wa_cost_price", q8((wc * wq + unitPrice * u.baseQty) / nq));
            latest.wa_quantity = rc("wa_costing_method", "wa_quantity", nq);
            touch("wa", latest);
          } else {
            const row = { id: newId("wa"), wa_cost_price: rc("wa_costing_method", "wa_cost_price", unitPrice), wa_quantity: rc("wa_costing_method", "wa_quantity", u.baseQty), material_id: mat, plant_id: plant, organization_id: org, created_at: nowText };
            waRows.push(row);
            created.wa.push(row);
          }
        }
      }
    }

    movementRows.push({
      operation_effect_key: s(input.operationKey) + "|" + key,
      transaction_type: trx,
      trx_no: m.trx_no,
      inventory_category: cat,
      parent_trx_no: m.parent_trx_no === undefined ? null : m.parent_trx_no,
      movement: "IN",
      plant_id: plant,
      organization_id: org,
      doc_date: m.doc_date,
      manufacturing_date: m.manufacturing_date === undefined ? null : m.manufacturing_date,
      expired_date: m.expired_date === undefined ? null : m.expired_date,
      unit_price: rc("inventory_movement", "unit_price", unitPrice),
      total_price: rc("inventory_movement", "total_price", totalPrice),
      quantity: rc("inventory_movement", "quantity", u.altQty),
      base_qty: rc("inventory_movement", "base_qty", u.baseQty),
      uom_id: u.altUOM,
      base_uom_id: u.baseUOM,
      item_id: mat,
      bin_location_id: loc,
      batch_number_id: batchId,
      costing_method_id: u.method,
      actual_qty: rc("inventory_movement", "actual_qty", u.altQty),
      actual_base_qty: rc("inventory_movement", "actual_base_qty", u.baseQty),
      handling_unit_id: m.handling_unit_id === undefined ? null : m.handling_unit_id,
    });
    const r = { movement_key: key, direction: dir, code: "200", batch_id: batchId, unit_price: unitPrice, total_price: totalPrice };
    results.push(r);
    byKey[key] = r;
  }

  const updates = {};
  for (const t of Object.keys(touched)) {
    updates[t] = Object.keys(touched[t]).map((id) => {
      const row = touched[t][id];
      const cols = Object.keys(before[t][id]);
      const after = {};
      for (const c of cols) after[c] = row[c] === undefined ? null : row[c];
      return { id, before: before[t][id], after };
    });
  }
  return { ok: true, results, updates, creates: created, movements: movementRows };
}

// SUBTRACT_INVENTORY_NEW code_node_BnKFTznr: weighted cost of the layers the quantity would use; a shortfall is
// priced at the highest-sequence layer, used up or not
function fifoUnitPrice(layers, baseQty) {
  if (!layers.length) return 0;
  const sorted = layers.slice().sort((a, b) => a.fifo_sequence - b.fifo_sequence);
  let remaining = q8(baseQty);
  let totalCost = 0;
  let totalQty = 0;
  for (const r of sorted) {
    if (remaining <= 0) break;
    const avail = q8(r.fifo_available_quantity || 0);
    if (avail <= 0) continue;
    const cost = q8(r.fifo_cost_price || 0);
    const take = Math.min(avail, remaining);
    totalCost = q8(totalCost + take * cost);
    totalQty = q8(totalQty + take);
    remaining = q8(remaining - take);
  }
  if (remaining > 0) {
    totalCost = q8(totalCost + remaining * q8(sorted[sorted.length - 1].fifo_cost_price || 0));
    totalQty = q8(totalQty + remaining);
  }
  return totalQty > 0 ? q8(totalCost / totalQty) : 0;
}


const arr = (v) => (Array.isArray(v) ? v : v ? [v] : []);
const dec = (v) => {
  const t = q8(v).toFixed(8).replace(/\.?0+$/, "");
  return t === "-0" || t === "" ? "0" : t;
};
const SLICE = 250;
const CHUNK = 400000;

const bulkPlan = function bulkPlan(inp) {
  if (s(inp.lockRoute) === "LOST") return { route: "LOST", result_code: "LOCK_BUSY", result_message: "Another operation took a lock before this one could" };
  const route0 = s(inp.route);
  const op = s(inp.operationKey);
  const org = s(inp.organizationId);
  let movements = inp.movements;
  if (typeof movements === "string") movements = JSON.parse(movements);
  const items = {};
  for (const r of arr(inp.items)) {
    let conv = r.uom_conversion_json;
    if (typeof conv === "string") {
      try {
        conv = JSON.parse(conv);
      } catch (e) {
        conv = [];
      }
    }
    items[s(r.id)] = {
      id: s(r.id),
      stock_control: Number(r.stock_control),
      based_uom: s(r.based_uom),
      material_costing_method: r.material_costing_method,
      purchase_unit_price: Number(r.purchase_unit_price || 0),
      item_batch_management: Number(r.item_batch_management || 0),
      table_uom_conversion: arr(conv).map((c) => ({ alt_uom_id: s(c.alt_uom_id), base_qty: Number(c.base_qty) })),
    };
  }
  const num = (rows, cols) =>
    arr(rows).map((r) => {
      const o = Object.assign({}, r);
      for (const c of cols) if (o[c] !== undefined && o[c] !== null && o[c] !== "") o[c] = Number(o[c]);
      return o;
    });
  const QTY = ["unrestricted_qty", "reserved_qty", "block_qty", "qualityinsp_qty", "intransit_qty", "balance_quantity"];
  const bal = num(inp.itemBalances, QTY);
  const batch = num(inp.batchBalances, QTY);
  const fifo = num(inp.fifoLayers, ["fifo_available_quantity", "fifo_cost_price"]).map((r) => Object.assign(r, { batch_id: s(r.batch_id) === "0" ? null : r.batch_id }));
  const wa = num(inp.waRows, ["wa_quantity", "wa_cost_price"]).map((r) => Object.assign(r, { batch_id: s(r.batch_id) === "0" ? null : r.batch_id }));

  // the tenant's number rules as configured now (defaults "Inventory Price" 4 / "Inventory Qty" 3, customisable per tenant
  // and per column): decimals, precision_rule (1 half-up, 2 toward zero, 3 away from zero), store_raw_value = no rounding
  const TABLE_OF = { "1902698977724317697": "item_balance", "1902718803880558594": "item_batch_balance", "1902947165008400386": "fifo_costing_history",
    "1902948453171433474": "wa_costing_method", "1902259348776800257": "inventory_movement", "1902719754154655746": "batch" };
  const precision = { price: null, qty: null, columns: {} };
  let precisionProblem = "";
  for (const r of arr(inp.precision)) {
    const mode = Number(r.precision_rule);
    const dp = Number(r.decimal_places);
    if ([1, 2, 3].indexOf(mode) < 0 || !(dp >= 0)) {
      precisionProblem = precisionProblem || "number rule " + s(r.rule_key || r.field_name) + ": precision_rule " + s(r.precision_rule) + ", decimals " + s(r.decimal_places);
      continue;
    }
    const rule = Number(r.store_raw_value) === 1 || dp >= 8 ? { dp: null, mode: mode } : { dp: dp, mode: mode };
    if (s(r.scope_type) === "2") {
      if (TABLE_OF[s(r.table_id)] && s(r.field_name)) precision.columns[TABLE_OF[s(r.table_id)] + "." + s(r.field_name)] = rule;
    } else if (s(r.rule_key) === "Inventory Price") precision.price = rule;
    else if (s(r.rule_key) === "Inventory Qty") precision.qty = rule;
  }

  let plan;
  let fromIntent = false;
  if (route0 === "RESUME") {
    plan = JSON.parse(s(inp.intentText));
    fromIntent = true;
  } else {
    if (precisionProblem) return { route: "FAIL", code: "400", result_code: "UNSUPPORTED_PRECISION", result_message: "The tenant's " + precisionProblem + " is not a rounding the platform documents" };
    plan = planBulk({ operationKey: op, items, itemBalances: bal, batchBalances: batch, fifoLayers: fifo, waRows: wa, movements, nowText: s(inp.dbNow), precision: precision });
    if (!plan.ok) {
      return { route: "FAIL", code: "400", result_code: plan.failure.code, result_message: plan.failure.message + " (movement " + plan.failure.movement_key + ")", failure: plan.failure, results: plan.results };
    }
    if (route0 === "PLAN") {
      return { route: "PLAN_OK", code: "200", result_code: "OK", result_message: "Planned " + plan.results.length + " movements", results: plan.results, summary: summaryOf(plan) };
    }
  }

  // which planned rows still need writing: equal to after -> done; equal to before -> write; else someone else changed it
  const current = {
    item_balance: index(bal),
    item_batch_balance: index(batch),
    fifo: index(fifo),
    wa: index(wa),
  };
  const conflicts = [];
  const pending = {};
  for (const t of ["item_balance", "item_batch_balance", "fifo", "wa"]) {
    pending[t] = [];
    for (const u of arr(plan.updates[t])) {
      const row = current[t][s(u.id)];
      if (!row) {
        conflicts.push(t + " " + u.id + " is gone");
        continue;
      }
      if (sameCols(row, u.after)) continue;
      if (sameCols(row, u.before)) pending[t].push(u);
      else conflicts.push(t + " " + u.id + " changed since the plan");
    }
  }
  const createsLeft = { item_balance: [], item_batch_balance: [], fifo: [], wa: [] };
  for (const t of Object.keys(createsLeft)) {
    for (const c of arr(plan.creates[t])) {
      if (!fromIntent) {
        createsLeft[t].push(c);
        continue;
      }
      const hit = findCreated(t, c, { item_balance: bal, item_batch_balance: batch, fifo, wa });
      if (hit === "SAME") continue;
      if (hit === "ABSENT") createsLeft[t].push(c);
      else conflicts.push(t + " new row " + naturalKey(t, c) + " differs");
